// Every refused call of the arms given, grouped by tool, with the arguments the model sent:
//   node refused.mjs <arm dir> [<arm dir> ...]
// And, per run, what each model response contained, in order (SEARCH is a hosted tool search), to tell a
// call made without searching for the tool first from one made after its parameters were loaded:
//   node refused.mjs --responses <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
const responses = process.argv[2] === '--responses';
for (const dir of process.argv.slice(responses ? 3 : 2)) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  if (responses) {
    for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.log')).sort()) {
      console.log(`\n${arm} ${file.replace('.log', '')}`);
      for (const line of fs.readFileSync(path.join(dir, file), 'utf8').split('\n').filter(l => l.includes('JUSPRIN LIVE REQUEST')))
        console.log('  ' + line.replace(/.*items=/, '').replace(/reasoning,?/g, '').replace(/openrouter:tool_search/g, 'SEARCH').replace(/function_call:\//g, 'call:').trim().slice(0, 200));
    }
    continue;
  }
  const byTool = {};
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    for (const c of r.refusedCalls) (byTool[`${c.tool} ${c.code}`] ??= []).push(`${file.replace('.json', '')}: ${c.arguments.slice(0, 300)}`);
  }
  console.log(`\n== ${arm}`);
  for (const [key, list] of Object.entries(byTool)) console.log(`${key} x${list.length}\n  ` + list.join('\n  '));
}
// Outcome facts for every record of the arms given: node outcomes.mjs <arm dir> [<arm dir> ...]
// Each arm dir holds <scenario>-<n>.json records. Prints one block per record, then totals per arm.
import fs from 'node:fs';
import path from 'node:path';
for (const dir of process.argv.slice(2)) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  const total = { runs: 0, failedTurns: 0, refused: 0, requests: 0, input: 0, cached: 0, output: 0 };
  const refusedBy = {};
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    let r;
    try { r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')); }
    catch (error) { console.log(`${arm} ${file}: unreadable (${error.message.slice(0, 60)})`); continue; }
    total.runs++; total.requests += r.usage.requests; total.input += r.usage.inputTokens; total.cached += r.usage.cachedInputTokens; total.output += r.usage.outputTokens;
    total.refused += r.refusedCalls.length;
    for (const c of r.refusedCalls) refusedBy[c.tool] = (refusedBy[c.tool] ?? 0) + 1;
    if (r.stopped !== 'completed') total.failedTurns++;
    const turns = r.turns.map((turn, index) => {
      const calls = turn.calls.map(c => c.tool + (c.state === 'succeeded' ? '' : '(' + c.state + ')'));
      const intents = turn.calls.filter(c => c.tool === 'intent_update' && c.state === 'succeeded').map(c =>
        `"${c.arguments.setupTitle ?? ''}" [` + (c.arguments.fields ?? []).map(f => `${f.field}=${f.value ?? '?' + (f.question ?? '')}${f.assumed ? '(assumed)' : ''}`).join('; ') + ']');
      const bad = turn.replies.filter(m => m.state !== 'complete').map(m => m.state + ' ' + (m.error ?? ''));
      return `  t${index}${turn.said === null ? '(file opened)' : ''}: ${calls.length} calls in order: ${calls.join(' > ') || '-'}` +
        (intents.length ? `\n      intent recorded: ${intents.join(' | ')}` : '') +
        (bad.length ? `\n      TURN ENDED BADLY: ${bad.join(',')}` : '');
    });
    const p = r.project, w = p.workspace ?? {};
    console.log(`\n${arm} ${file.replace('.json', '')}: ${r.stopped} requests=${r.usage.requests} input=${r.usage.inputTokens} refused=${r.refusedCalls.length}${r.refusedCalls.length ? ' (' + r.refusedCalls.map(c => c.tool).join(',') + ')' : ''}`);
    console.log(turns.join('\n'));
    console.log(`  END filament=${p.filamentPreset} | process=${p.processPreset} | changed settings=${p.changedSettings.map(c => c.key + '=' + c.value).join(',') || 'none'} | sliced=${(w.slicing?.plates ?? []).map(x => x.sliced).join(',')}`);
    console.log(`  END intent fields: ${(w.intent?.fields ?? []).map(f => `${f.field}=${f.value}(${f.provenance})`).join('; ') || 'none'} | plan=${w.plan?.headline ? 'set' : 'none'}`);
  }
  console.log(`\nTOTAL ${arm}: ${JSON.stringify(total)} refused by tool: ${JSON.stringify(refusedBy)}`);
}
// What one run actually sent: node sent.mjs <record.json> [--write <dir>]
// With --write, saves the instructions and each tool's description for an experiment to edit from.
import fs from 'node:fs';
import path from 'node:path';
const r = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const sent = r.route.sent;
if (!sent) { console.log('this record sent no request with tools'); process.exit(1); }
console.log(`experiment: "${sent.experiment}"  instructions: ${sent.instructions.length} chars`);
console.log(`loaded tools:   ${sent.tools.filter(t => !t.deferred).map(t => t.name).join(', ')}`);
console.log(`deferred tools: ${sent.tools.filter(t => t.deferred).map(t => t.name).join(', ')}`);
const at = process.argv.indexOf('--write');
if (at > 0) {
  const dir = process.argv[at + 1];
  fs.writeFileSync(path.join(dir, 'control-instructions.txt'), sent.instructions);
  fs.writeFileSync(path.join(dir, 'control-tools.json'),
    JSON.stringify(Object.fromEntries(sent.tools.map(t => [t.name, { deferred: t.deferred, description: t.description }])), null, 2));
  console.log('wrote control-instructions.txt and control-tools.json to ' + dir);
}

