// Sorts every refused call of the arms given into: blind (a deferred tool called with no SEARCH earlier in the
// turn), searched (a SEARCH came earlier in the same turn; "known" when the same tool had already run in that
// turn), loaded (the tool was sent with its parameters), and unknown (no such tool).
//   node classify.mjs <arm dir> [<arm dir> ...]        add --detail for one line per refused call
// The log gives each response's items in order; the record gives the executed calls and the refused calls,
// each in order. The app acts on the first function call of a response, so that call is either the next
// executed call or the next refused one; where both fit, the refusal is taken first (a refusal is followed by
// the corrected call far more often than the reverse) and the run is marked ambiguous.
import fs from 'node:fs';
import path from 'node:path';
const detail = process.argv.includes('--detail');
const alwaysLoaded = new Set(['settings_get', 'settings_search', 'workspace_inspect']);
for (const dir of process.argv.slice(2).filter(a => !a.startsWith('--'))) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  const sum = { blind: 0, searched: 0, searchedKnown: 0, loaded: 0, unknown: 0, searches: 0, blindAccepted: 0, unaligned: 0, ambiguous: 0 };
  const byTool = {};
  const lines = [];
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json') && fs.existsSync(path.join(dir, f.replace('.json', '.log')))).sort()) {
    const run = file.replace('.json', '');
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    const loaded = new Set(r.route?.sent?.tools ? r.route.sent.tools.filter(t => !t.deferred).map(t => t.name) : alwaysLoaded);
    const known = new Set(r.route?.sent?.tools ? r.route.sent.tools.map(t => t.name) : []);
    const executed = r.turns.flatMap(t => t.calls.map(c => c.tool));
    const refused = r.refusedCalls.map(c => c);
    let e = 0, f = 0, turn = 0, searchedThisTurn = false, ranThisTurn = new Set();
    for (const line of fs.readFileSync(path.join(dir, run + '.log'), 'utf8').split('\n')) {
      if (/HARNESS CHECK journey_(opening_message|turn_\d+_ended)/.test(line)) { turn++; searchedThisTurn = false; ranThisTurn = new Set(); continue; }
      if (!line.includes('JUSPRIN LIVE REQUEST')) continue;
      const items = line.replace(/.*items=/, '').trim().split(',');
      const callAt = items.findIndex(i => i.startsWith('function_call:/'));
      const searchesBefore = items.slice(0, callAt < 0 ? items.length : callAt).filter(i => i === 'openrouter:tool_search').length;
      sum.searches += items.filter(i => i === 'openrouter:tool_search').length;
      if (searchesBefore) searchedThisTurn = true;
      if (callAt < 0) continue;
      const tool = items[callAt].replace('function_call:/', '');
      const fitsRefused = f < refused.length && refused[f].tool === tool, fitsExecuted = e < executed.length && executed[e] === tool;
      if (fitsRefused && fitsExecuted) sum.ambiguous++;
      if (fitsRefused) {
        const c = refused[f++];
        let kind;
        if (c.code === 'unknown_tool') kind = 'unknown';
        else if (loaded.has(tool)) kind = 'loaded';
        else if (!searchedThisTurn) kind = 'blind';
        else kind = ranThisTurn.has(tool) ? 'searchedKnown' : 'searched';
        sum[kind]++;
        (byTool[tool] ??= { blind: 0, searched: 0, searchedKnown: 0, loaded: 0, unknown: 0 })[kind]++;
        lines.push(`  ${run} t${turn} ${kind.padEnd(13)} ${tool} ${c.arguments.slice(0, 220)}`);
      } else if (fitsExecuted) {
        e++;
        if (!loaded.has(tool) && !searchedThisTurn) sum.blindAccepted++;
        ranThisTurn.add(tool);
      } else { sum.unaligned++; lines.push(`  ${run} t${turn} UNALIGNED call ${tool}`); }
      if (items.slice(callAt).includes('openrouter:tool_search')) searchedThisTurn = true;
    }
    if (e !== executed.length || f !== refused.length) lines.push(`  ${run} LEFT OVER executed ${executed.length - e} refused ${refused.length - f}`);
  }
  console.log(`\n== ${arm}: ${JSON.stringify(sum)}`);
  for (const [tool, k] of Object.entries(byTool)) console.log(`  ${tool.padEnd(24)} blind ${k.blind}  searched ${k.searched}  searched+ran ${k.searchedKnown}  loaded ${k.loaded}  unknown ${k.unknown}`);
  if (detail) console.log(lines.join('\n'));
}

