// Sorts every refused call of the arms given by what the model could see when it made the call:
//   blind      a deferred tool, no SEARCH anywhere earlier in the turn: its parameters were certainly not loaded
//   unsearched a deferred tool, no SEARCH in this response before the call and the tool has not run in this turn,
//              but an earlier response of the turn did search (for what, the log does not say): probably blind
//   seen       a SEARCH came in the same response before the call, or the tool already ran in this turn:
//              its parameters were in front of the model
//   loaded     the tool was sent with its parameters
//   unknown    there is no tool of that name
//   node classify.mjs <arm dir> [<arm dir> ...]        add --detail for one line per refused call
// The log gives each response's items in order and where each turn ends; the record gives each turn's executed
// calls and the run's refused calls, each in order. The app acts on the first function call of a response, so
// a turn's refusals are its processed calls less its executed ones. Within a turn, where a call could be
// either, the refusal is taken first (a refusal is followed by the corrected call far more often than the
// reverse), provided the rest of the turn still lines up; such choices are counted as ambiguous.
import fs from 'node:fs';
import path from 'node:path';
const detail = process.argv.includes('--detail');
const alwaysLoaded = new Set(['settings_get', 'settings_search', 'workspace_inspect']);
const kinds = ['blind', 'unsearched', 'seen', 'loaded', 'unknown'];
const blank = () => ({ blind: 0, unsearched: 0, seen: 0, loaded: 0, unknown: 0 });

// Which of a turn's processed calls were refused: true per call, or null when the two lists do not line up.
function assign(calls, executed, refused) {
  let ambiguous = 0;
  const walk = (i, e, f) => {
    if (i === calls.length) return e === executed.length && f === refused.length ? [] : null;
    const canRefuse = f < refused.length && refused[f] === calls[i], canRun = e < executed.length && executed[e] === calls[i];
    if (canRefuse) { const rest = walk(i + 1, e, f + 1); if (rest) { if (canRun && walk(i + 1, e + 1, f)) ambiguous++; return [true, ...rest]; } }
    if (canRun) { const rest = walk(i + 1, e + 1, f); if (rest) return [false, ...rest]; }
    return null;
  };
  const marks = walk(0, 0, 0);
  return { marks, ambiguous };
}

for (const dir of process.argv.slice(2).filter(a => !a.startsWith('--'))) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  const sum = { ...blank(), searches: 0, deferredRanWithNoSearchInTurn: 0, turnsNotAligned: 0, ambiguous: 0 };
  const byTool = {}, byScenario = {};
  const lines = [];
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json') && fs.existsSync(path.join(dir, f.replace('.json', '.log')))).sort()) {
    const run = file.replace('.json', '');
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    const loaded = new Set(r.route?.sent?.tools ? r.route.sent.tools.filter(t => !t.deferred).map(t => t.name) : alwaysLoaded);
    const scenario = (byScenario[r.scenario] ??= { ...blank(), searches: 0 });
    // The log, as turns of responses.
    const turns = [[]];
    for (const line of fs.readFileSync(path.join(dir, run + '.log'), 'utf8').split('\n')) {
      if (/HARNESS CHECK journey_(opening_message|turn_\d+_ended)/.test(line)) { turns.push([]); continue; }
      if (line.includes('JUSPRIN LIVE REQUEST')) turns.at(-1).push(line.replace(/.*items=/, '').trim().split(','));
    }
    let f = 0;
    turns.forEach((responses, turn) => {
      const executed = (r.turns[turn]?.calls ?? []).map(c => c.tool);
      const processed = responses.map(items => items.find(i => i.startsWith('function_call:/'))?.replace('function_call:/', '')).filter(Boolean);
      const count = processed.length - executed.length;
      const mine = count >= 0 ? r.refusedCalls.slice(f, f + count) : [];
      const { marks, ambiguous } = assign(processed, executed, mine.map(c => c.tool));
      sum.ambiguous += ambiguous;
      if (!marks) { sum.turnsNotAligned++; lines.push(`  ${run} t${turn} NOT ALIGNED: log calls ${processed.join(',')} | executed ${executed.join(',')} | refused ${mine.map(c => c.tool).join(',')}`); }
      let searchedThisTurn = false, at = 0, taken = 0;
      const ran = new Set();
      for (const items of responses) {
        const callAt = items.findIndex(i => i.startsWith('function_call:/'));
        const searches = items.filter(i => i === 'openrouter:tool_search').length;
        sum.searches += searches; scenario.searches += searches;
        if (callAt >= 0 && marks) {
          const tool = items[callAt].replace('function_call:/', '');
          const searchBeforeCall = items.slice(0, callAt).includes('openrouter:tool_search');
          if (marks[at]) {
            const c = mine[taken++];
            const kind = c.code === 'unknown_tool' ? 'unknown' : loaded.has(tool) ? 'loaded'
              : searchBeforeCall || ran.has(tool) ? 'seen' : searchedThisTurn ? 'unsearched' : 'blind';
            sum[kind]++; scenario[kind]++; (byTool[tool] ??= blank())[kind]++;
            lines.push(`  ${run} t${turn} ${kind.padEnd(10)} ${tool} ${c.arguments.slice(0, 230)}`);
          } else {
            if (!loaded.has(tool) && !searchedThisTurn && !searchBeforeCall) sum.deferredRanWithNoSearchInTurn++;
            ran.add(tool);
          }
          at++;
        }
        if (searches) searchedThisTurn = true;
      }
      f += Math.max(count, 0);
    });
    if (f !== r.refusedCalls.length) lines.push(`  ${run} REFUSED CALLS NOT PLACED: ${r.refusedCalls.length - f}`);
  }
  console.log(`\n== ${arm}: ${JSON.stringify(sum)}`);
  for (const [tool, k] of Object.entries(byTool)) console.log(`  ${tool.padEnd(24)} ` + kinds.map(x => `${x} ${k[x]}`).join('  '));
  for (const [name, k] of Object.entries(byScenario)) console.log(`  [${name}] ` + kinds.map(x => `${x} ${k[x]}`).join('  ') + `  searches ${k.searches}`);
  if (detail) console.log(lines.join('\n'));
}

