// Input tokens per arm and per scenario, with requests and the size of the opening request (the fixed cost of
// what is sent before any search).   node tokens.mjs <arm dir> [<arm dir> ...]
import fs from 'node:fs';
import path from 'node:path';
const k = n => (n / 1000).toFixed(0) + 'k';
for (const dir of process.argv.slice(2)) {
  const arm = path.basename(path.dirname(dir)) + '/' + path.basename(dir);
  const by = {};
  const all = { input: 0, cached: 0, output: 0, requests: 0, opening: [] };
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    const s = (by[r.scenario] ??= { input: 0, cached: 0, output: 0, requests: 0, runs: [] });
    for (const t of [s, all]) { t.input += r.usage.inputTokens; t.cached += r.usage.cachedInputTokens; t.output += r.usage.outputTokens; t.requests += r.usage.requests; }
    s.runs.push(k(r.usage.inputTokens));
    all.opening.push(r.turns[0].requests[0].inputTokens);
  }
  const usd = (all.input * 0.091 + all.output * 0.182) / 1e6;
  console.log(`\n== ${arm}: input ${k(all.input)} (cached ${k(all.cached)}) output ${k(all.output)} requests ${all.requests} input/request ${k(all.input / all.requests)} list $${usd.toFixed(3)} opening request ${Math.min(...all.opening)}-${Math.max(...all.opening)}`);
  for (const [name, s] of Object.entries(by)) console.log(`  ${name.padEnd(16)} input ${k(s.input).padStart(6)}  requests ${String(s.requests).padStart(3)}  input/request ${k(s.input / s.requests).padStart(4)}  runs ${s.runs.join(' ')}`);
}

