cd "C:/Users/guitest/AppData/Local/Temp/claude/C--src-JusPrin/71e3bd46-c856-4b36-b7cc-979fe94e0bdf/scratchpad/exp" && cat > blind-calls/attempts.mjs <<'EOF'
// Per arm: for the six tools the instructions name, calls that ran and calls refused.  node attempts.mjs <arm dir>...
import fs from 'node:fs';
import path from 'node:path';
const named = ['intent_update', 'object_analyze', 'presets_list', 'plan_set', 'slice_report', 'slice_start'];
for (const dir of process.argv.slice(2)) {
  const ran = {}, refused = {};
  let otherRan = 0, otherRefused = 0;
  for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.json'))) {
    const r = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8'));
    for (const t of r.turns) for (const c of t.calls) named.includes(c.tool) ? ran[c.tool] = (ran[c.tool] ?? 0) + 1 : otherRan++;
    for (const c of r.refusedCalls) named.includes(c.tool) ? refused[c.tool] = (refused[c.tool] ?? 0) + 1 : otherRefused++;
  }
  const sum = o => Object.values(o).reduce((a, b) => a + b, 0);
  console.log(path.basename(dir).padEnd(13) + named.map(n => `${n} ${refused[n] ?? 0}/${(ran[n] ?? 0) + (refused[n] ?? 0)}`).join('  ') + `  | named ${sum(refused)}/${sum(ran) + sum(refused)}  other ${otherRefused}/${otherRan + otherRefused}`);
}
